<?php
require dirname(__DIR__).'/bootstrap.php';
use AranduGo\Database;use AranduGo\Support;
$token=(string)($_GET['token']??$_POST['token']??'');$error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'){$password=(string)($_POST['password']??'');if(strlen($password)<10)$error='La contraseña debe tener al menos 10 caracteres.';else{$resets=Database::table('password_resets');$users=Database::table('users');$stmt=Database::connection()->prepare("SELECT user_id FROM {$resets} WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1");$stmt->execute([hash('sha256',$token)]);$row=$stmt->fetch();if(!$row)$error='El enlace no es válido o venció.';else{$pdo=Database::connection();$pdo->beginTransaction();$pdo->prepare("UPDATE {$users} SET password_hash=?,failed_attempts=0,failed_at=NULL WHERE id=?")->execute([password_hash($password,PASSWORD_DEFAULT),$row['user_id']]);$pdo->prepare("UPDATE {$resets} SET used_at=NOW() WHERE token_hash=?")->execute([hash('sha256',$token)]);$pdo->commit();$done=true;}}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nueva contraseña</title><link rel="stylesheet" href="<?=Support::url('assets/dashboard.css')?>"></head><body><main class="login"><form class="login-card" method="post"><div class="brand"><span class="mark">A</span><strong>Arandu Go</strong></div><h1>Nueva contraseña</h1><?php if($done):?><p class="notice">La contraseña fue actualizada.</p><a class="btn blue" href="<?=Support::url('dashboardcliente/login.php')?>">Ingresar</a><?php else:?><?php if($error):?><p class="error"><?=Support::e($error)?></p><?php endif;?><input type="hidden" name="token" value="<?=Support::e($token)?>"><label class="field">Contraseña nueva<input type="password" name="password" minlength="10" required autofocus></label><p><button class="btn blue">Guardar contraseña</button></p><?php endif;?></form></main></body></html>
